r5_model_input <- function(input,pre,unit){get<-function(k,d=NULL)input[[paste0(pre,k)]] %||% d;f<-time_factor(unit);model<-get("model","exponential");m<-get("median",12)*f;if(model=="exponential"&&get("exp_basis","median")=="rate")m<-log(2)/(get("rate",log(2)/12)/f);parameter_model(model,list(median=m,shape=get("shape",1.2),rates=parse_unit_numbers(get("rates","0.04,0.06,0.05"))/f),if(model=="pwe")parse_unit_numbers(get("cuts","6,12"))*f else numeric())}
r5_read_csv <- function(text)tryCatch(read.csv(text=text,stringsAsFactors=FALSE,check.names=FALSE),error=function(e)stop("请填写有列名的CSV。"))
r5_csv_text <- function(d){p<-textConnection("r5_lines","w",local=TRUE);write.csv(d,p,row.names=FALSE);close(p);paste(r5_lines,collapse="\n")}
ma_input <- function(input,pre="ma_"){get<-function(k,d=NULL)input[[paste0(pre,k)]] %||% d;u<-get("unit","months");f<-time_factor(u);design<-get("design","final");arms<-r5_read_csv(get("arms"));if("dropout_rate" %in% names(arms))arms$dropout_rate<-arms$dropout_rate/f;sc<-r5_read_csv(get(if(design=="two_in_one")"scenario_joint" else "scenario_single"));stage1<-get("stage1",18)*f;cfg<-list(research_family="multiarm_independent_design",purpose=design,design=design,mode="fixed_truth",design_mode="independent_stages",effect_mode="ph",primary="design",sided="benefit",alpha=get("alpha",.025),origin=as.character(get("origin","2025-01-01")),display_unit=u,engine_unit="days",paramcd=if(design=="two_in_one")"OS" else get("endpoint","PFS"),control_model=if(design=="two_in_one")parameter_model("exponential",list(median=log(2)/(get("death_rate",log(2)/30)/f))) else r5_model_input(input,pre,u),progression_rate=get("progression_rate",log(2)/12)/f,death_rate=get("death_rate",log(2)/30)/f,arms=arms,scenario_table=sc,n1=get("n1",300),n2=if(design=="final")20 else get("n2",300),stage1_day=stage1,max_day=if(design=="final")stage1 else get("max",42)*f,landmark_age=if(get("test","logrank")=="landmark_exact")get("landmark",12)*f else f,enroll_rate=get("enroll_rate",30)/f,test=get("test","logrank"),multiplicity=get("multiplicity","bonferroni"),confirmation=if(design=="final")"stage2" else get("confirmation","combination"),w1=if(design=="final"||get("confirmation","combination")=="stage2")sqrt(.5) else get("w1",sqrt(.5)),screen_p=if(design=="final")1 else get("screen_p",.5),select_k=if(design=="final")nrow(arms)-1 else get("select_k",1),reps=get("reps",100),seed=get("seed",20261005),cut_rule=get("cut_rule","fixed"),event_d1=get("event_d1",120),event_d2=if(design=="final")1L else get("event_d2",120),dunnett_steps=get("dunnett_steps",128L),interval_enabled=get("test","logrank")=="cox_wald"&&isTRUE(get("interval_enabled",FALSE)),interval_alpha=get("interval_alpha",.05),filter_enabled=FALSE,reference_scenario=1);cfg}
ds_input <- function(input){b<-ma_input(input,"ds_");d<-r5_read_csv(input$ds_candidates);keys<-c("label","n1","n2","stage1","max","landmark","w1");if(!all(keys %in% names(d))||any(!names(d) %in% c(keys,"event_d1","event_d2")))stop("候选七列label,n1,n2,stage1,max,landmark,w1；事件模式另加event_d1/event_d2。");if(mx_rule(b)=="target"&&!all(c("event_d1","event_d2") %in% names(d)))stop("事件驱动候选需event_d1,event_d2列。");if(mx_rule(b)=="fixed"){d$event_d1<-0;d$event_d2<-0}else if(b$design=="final")d$event_d2<-1L;f<-time_factor(b$display_unit);for(k in c("stage1","max","landmark"))d[[k]]<-d[[k]]*f;names(d)[match(c("stage1","max","landmark"),names(d))]<-c("stage1_day","max_day","landmark_age");if(b$design=="final"){d$n2<-20;d$max_day<-d$stage1_day;d$w1<-sqrt(.5)};if(b$test!="landmark_exact")d$landmark_age<-f;if(b$confirmation=="stage2")d$w1<-sqrt(.5);cfg<-list(research_family="finite_design_search",mode="fixed_truth",design_mode="finite_search",effect_mode="ph",primary="search",sided="benefit",alpha=b$alpha,origin=b$origin,paramcd=b$paramcd,display_unit=b$display_unit,engine_unit="days",base=b,candidate_table=d,power_target=input$ds_power_target,fwer_limit=input$ds_fwer_limit,confidence=input$ds_confidence,day_cost=input$ds_day_cost,reps=input$ds_reps,seed=input$ds_seed,cut_rule="fixed",filter_enabled=FALSE,reference_scenario=1);validate_design_search(cfg);cfg}
rc_input <- function(input){u<-input$rc_unit %||% "months";f<-time_factor(u);solve<-input$rc_solve;surv<-solve=="survival";list(solve=solve,model=r5_model_input(input,"rc_",u),n0=if(surv)0 else input$rc_n0,future_n=if(surv||solve=="future_n")1 else input$rc_future_n,accrual_day=if(surv)f else input$rc_accrual*f,dco_day=if(surv)input$rc_age*f else if(solve=="dco")f else input$rc_dco*f,dropout_rate=if(surv)0 else input$rc_dropout/f,hazard_q=if(solve %in% c("hazard","survival"))1 else input$rc_hazard_q,target_events=if(surv)0 else input$rc_target,survival_age=input$rc_age*f,survival_target=input$rc_survival,bounds=c(input$rc_lower,input$rc_upper)*if(solve=="dco")f else 1,display_unit=u,engine_unit="days")}
register_r5_units <- function(input,session,pre){old<-reactiveVal("months");id<-function(k)paste0(pre,k);observeEvent(input[[id("unit")]],{to<-input[[id("unit")]];from<-old();if(to==from)return();ratio<-time_factor(from)/time_factor(to);label<-time_label(to);nums<-function(x)paste(format(x,digits=16,trim=TRUE),collapse=",");for(k in c("median","stage1","max","landmark","accrual","dco","age")){v<-isolate(input[[id(k)]]);if(!is.null(v)){freezeReactiveValue(input,id(k));updateNumericInput(session,id(k),label=parameter_label(id(k),paste0(switch(k,median="中位时间",stage1="Final / Stage1日历时间",max="共同Final日历时间",landmark="参考随访年龄",accrual="均匀入组期",dco="DCO",age="生存参考年龄"),"（",label,"）")),value=v*ratio)}};for(k in c("rate","progression_rate","death_rate","enroll_rate","dropout")){v<-isolate(input[[id(k)]]);if(!is.null(v)){freezeReactiveValue(input,id(k));updateNumericInput(session,id(k),label=parameter_label(id(k),paste0(switch(k,rate="风险率",progression_rate="进展风险率",death_rate="死亡风险率",enroll_rate="每阶段总体入组率",dropout="独立退出率"),"（每",label,"）")),value=v/ratio)}};for(k in c("cuts","rates")){v<-isolate(input[[id(k)]]);if(!is.null(v)){x<-tryCatch(nums(parse_unit_numbers(v)*if(k=="cuts")ratio else 1/ratio),error=function(e)v);freezeReactiveValue(input,id(k));updateTextInput(session,id(k),label=parameter_label(id(k),if(k=="cuts")paste0("风险年龄切点（",label,"）") else paste0("各段风险率（每",label,"）")),value=x)}}
    for(k in c("arms","candidates")){v<-isolate(input[[id(k)]]);if(is.null(v))next;x<-tryCatch({d<-r5_read_csv(v);if(k=="arms")d$dropout_rate<-d$dropout_rate/ratio else for(z in intersect(c("stage1","max","landmark"),names(d)))d[[z]]<-d[[z]]*ratio;r5_csv_text(d)},error=function(e)v);freezeReactiveValue(input,id(k));updateTextAreaInput(session,id(k),label=parameter_label(id(k),if(k=="arms")paste0("arm,weight,dropout_rate（每",label,"）") else paste0("label,n1,n2,stage1,max,landmark,w1（时间为",label,"）")),value=x)}
    if(pre=="rc_"&&isolate(input$rc_solve)=="dco")for(k in c("lower","upper")){v<-isolate(input[[id(k)]]);freezeReactiveValue(input,id(k));updateNumericInput(session,id(k),value=v*ratio)};old(to)},ignoreInit=TRUE)
  observeEvent(input[[id("exp_basis")]],{if(isolate(input[[id("model")]])!="exponential")return();if(input[[id("exp_basis")]]=="rate"){v<-isolate(input[[id("median")]]);if(is.finite(v)&&v>0)updateNumericInput(session,id("rate"),value=log(2)/v)}else {v<-isolate(input[[id("rate")]]);if(is.finite(v)&&v>0)updateNumericInput(session,id("median"),value=log(2)/v)}},ignoreInit=TRUE)}
register_round_five_server <- function(input,output,session,controller){register_r5_units(input,session,"ma_");register_r5_units(input,session,"ds_");register_r5_units(input,session,"rc_");ma<-register_research_workbench_server(input,output,session,controller,"ma_","multiarm_independent_design","multiarm","ma_tabs",function(){c<-ma_input(input);validate_multiarm(c);c},ma_sample,ma_report,"run_multiarm",extra=c("arm_overview","intersection_overview","covariance_overview","interval_overview"),input_tabs="ma_inputs");ds<-register_research_workbench_server(input,output,session,controller,"ds_","finite_design_search","design_search","ds_tabs",function()ds_input(input),ds_sample,ds_report,"run_design_search",extra=c("candidate_overview","selection_record","confirmation_overview","confirmation_decision","intersection_overview","covariance_overview","interval_overview"),input_tabs=c("ds_base","ds_plan"))
  for(a in list(list(pre="ma_",bridge=ma),list(pre="ds_",bridge=ds)))local({pre<-a$pre;bridge<-a$bridge;output[[paste0(pre,"adtte_download")]]<-downloadHandler(filename=paste0(pre,"selected_adtte.csv"),content=function(file){r<-bridge$result();o<-bridge$sample()$observed;cfg<-r$config;if(ds_is(cfg))cfg<-cfg$base;d<-research_adtte(o,cfg,"COHORT");d$PARAMCD<-o$PARAMCD;write.csv(d,file,row.names=FALSE)});output[[paste0(pre,"status")]]<-renderUI({r<-bridge$result();e<-controller$error();tagList(if(!is.null(e))p(class="field-note",e),if(is.null(r))p(class="field-note","运行后显示冻结设计结果；开发稿待验证。") else p(class="field-note",paste0("v",r$version,"；已处理",r$completed,"/",r$total,"任务；",r$status,"。",if(pre=="ds_")"未选候选确认任务标记跳过；确认结果不参与选择，不能追加B。" else "主成功是有效臂声明；FWER单独报告。")))})})
  saved<-reactiveVal(NULL);note<-reactiveVal("求解结果按本次冻结参数保存；开发稿待验证。");output$rc_status<-renderUI(p(class="field-note",note()));observeEvent(input$rc_solve,{u<-time_factor(isolate(input$rc_unit %||% "months"));bounds<-switch(input$rc_solve,hazard=c(.01,10),survival=c(.01,10),future_n=c(0,10000),dco=c(0,3650/u));updateNumericInput(session,"rc_lower",label=parameter_label("rc_lower",if(input$rc_solve=="dco")paste0("DCO下界（",time_label(isolate(input$rc_unit)),"）") else "下界",value=bounds[1]);updateNumericInput(session,"rc_upper",label=parameter_label("rc_upper",if(input$rc_solve=="dco")paste0("DCO上界（",time_label(isolate(input$rc_unit)),"）") else "上界",value=bounds[2])},ignoreInit=TRUE)
  observeEvent(input$rc_run,{tryCatch({if(input$rc_source=="json"){req(input$rc_file);if(file.info(input$rc_file$datapath)$size>5*1024^2)stop("JSON最多5MB。");d<-jsonlite::read_json(input$rc_file$datapath,simplifyVector=FALSE);if(!identical(d$schema,"event_pred.reverse_config.v1"))stop("请选择本入口校准JSON。");cfg<-batch_decode_tree(d$exact_config);if(!identical(batch_config_hash(cfg),d$configuration_hash))stop("冻结配置摘要不符。")}else cfg<-rc_input(input);r<-run_reverse_calibration(cfg);saved(r);note("求解记录已生成；代码和数值尚未验证。")},error=function(e){saved(NULL);note(conditionMessage(e))})},ignoreInit=TRUE)
  output$rc_overview<-renderDT({r<-saved();req(r);d<-r$overview;if(r$config$solve=="dco"){d$solution<-d$solution/time_factor(r$config$display_unit);d$solver_lower<-d$solver_lower/time_factor(r$config$display_unit);d$solver_upper<-d$solver_upper/time_factor(r$config$display_unit);d$unit<-r$config$display_unit};study_table(d)});output$rc_trace<-renderDT({r<-saved();req(r);d<-r$trace;if(r$config$solve=="dco")d$value<-d$value/time_factor(r$config$display_unit);study_table(d)});output$rc_curve<-renderPlotly({r<-saved();req(r);d<-r$curve;d$display_time<-d$day/time_factor(r$config$display_unit);if(r$config$solve=="survival")p<-ggplot(d,aes(display_time,survival))+geom_line(color="#126b72")+labs(x=paste0("随访年龄（",time_label(r$config$display_unit),"）"),y="模型生存率") else p<-ggplot(d,aes(display_time,expected_events))+geom_line(color="#126b72")+labs(x=paste0("研究经过时间（",time_label(r$config$display_unit),"）"),y="期望累计临床事件数");ggplotly(p)})
  output$rc_config_download<-downloadHandler(filename="reverse_config.json",content=function(file){r<-saved();req(r);jsonlite::write_json(list(schema="event_pred.reverse_config.v1",version=r$version,configuration_hash=batch_config_hash(r$config),exact_config=batch_encode_tree(r$config)),file,auto_unbox=TRUE,pretty=TRUE,digits=NA)});output$rc_result_download<-downloadHandler(filename="reverse_result_draft.rds",content=function(file){r<-saved();req(r);saveRDS(r,file,version=3)});for(k0 in c("overview","curve","trace"))local({k<-k0;output[[paste0("rc_",k,"_download")]]<-downloadHandler(filename=paste0("reverse_",k,"_days.csv"),content=function(file){r<-saved();req(r);write.csv(r[[k]],file,row.names=FALSE)})});output$rc_report_download<-downloadHandler(filename="reverse_report_draft.md",content=function(file){r<-saved();req(r);writeLines(rc_report(r),file,useBytes=TRUE)});output$rc_script_download<-downloadHandler(filename="reverse_replay_draft.R",content=function(file){r<-saved();req(r);dump<-paste(capture.output(dput(r$config,control=c("keepNA","keepInteger","niceNames","showAttributes","hexNumeric"))),collapse="\n");writeLines(c('source("R/research_sources.R")',paste0("cfg <- ",dump),paste0('if(batch_version!="',r$version,'" || batch_source_hash()!="',r$source_hash,'")stop("Source/version differs")'),paste0("expected_dependencies <- ",paste(capture.output(dput(r$dependencies)),collapse="\n")),'if(!identical(batch_dependencies(list()),expected_dependencies))stop("Dependencies differ")','result <- run_reverse_calibration(cfg)','saveRDS(result,"reverse_replayed.rds")','write.csv(result$overview,"reverse_overview_replayed.csv",row.names=FALSE)'),file,useBytes=TRUE)})
}
